-- Four UK learning journeys. Existing foundation progress is retained.
-- Content sources and review date are stored with each lesson.
begin;
create table public.cs_journeys (
 id text primary key, title text not null, description text not null,
 units jsonb not null, flexible boolean not null default false,
 visible boolean not null default true, position integer not null
);
alter table public.cs_journeys enable row level security;
revoke all on public.cs_journeys from anon, authenticated;
grant all on public.cs_journeys to service_role;
alter table public.cs_lessons add column journey_id text not null default 'foundations' references public.cs_journeys(id);
alter table public.cs_lessons add column journey_position integer;
update public.cs_lessons set journey_position=position;
alter table public.cs_lessons alter column journey_position set not null;
alter table public.cs_lessons add constraint cs_lessons_journey_order unique(journey_id,journey_position);
alter table public.cs_lessons add column reading_cards jsonb not null default '[]';
alter table public.cs_lessons add column checklist jsonb not null default '[]';
alter table public.cs_lessons add column sources jsonb not null default '[]';
alter table public.cs_lessons add column reviewed_at date;

alter table public.cs_learners add column active_journey text not null default 'university' references public.cs_journeys(id);
create or replace function public.cs_complete_lesson(p_learner uuid,p_lesson text,p_answers jsonb,p_attempt uuid)
returns jsonb language plpgsql security invoker set search_path = public as $$
declare
 l cs_lessons%rowtype; a cs_attempts%rowtype; score_count integer; total_count integer;
 passed_result boolean; awarded integer := 0;
begin
 -- Serialize submissions for this learner, including repeated requests.
 perform 1 from cs_learners where id=p_learner for update;
 if not found then raise exception 'Unknown learner'; end if;
 select * into a from cs_attempts where id=p_attempt;
 if found then
  if a.learner_id <> p_learner or a.lesson_id <> p_lesson or a.answers <> p_answers then raise exception 'Attempt mismatch'; end if;
  return jsonb_build_object('score',a.score,'total',a.total,'passed',a.passed,'awarded',0);
 end if;
 select * into l from cs_lessons where id=p_lesson;
 if not found then raise exception 'Unknown lesson'; end if;
 if not (select flexible from cs_journeys where id=l.journey_id) and exists(select 1 from cs_lessons prior where prior.journey_id=l.journey_id and prior.journey_position < l.journey_position and not exists(select 1 from cs_completions c where c.learner_id=p_learner and c.lesson_id=prior.id)) then raise exception 'Lesson locked'; end if;
 select count(*) into total_count from cs_questions where lesson_id=p_lesson;
 if jsonb_typeof(p_answers) <> 'array' or jsonb_array_length(p_answers) <> total_count or total_count = 0 then raise exception 'Invalid answers'; end if;
 if exists(select 1 from cs_questions q where q.lesson_id=p_lesson and (jsonb_typeof(p_answers->(q.position-1)) <> 'number' or (p_answers->>(q.position-1)) !~ '^[0-9]+$' or (p_answers->>(q.position-1))::integer >= jsonb_array_length(q.options))) then raise exception 'Invalid answer'; end if;
 select count(*) into score_count from cs_questions q where q.lesson_id=p_lesson and (p_answers->>(q.position-1))::integer=q.correct_index;
 passed_result := score_count >= ceil(total_count * 0.66);
 if passed_result then
  if found then awarded := l.xp; end if;
 end if;
 return jsonb_build_object('score',score_count,'total',total_count,'passed',passed_result,'awarded',awarded);
end $$;

commit;
