insert into public.cs_journeys values ('foundations','Original foundations','Your original learning history.', '["Budgeting","Saving","Interest"]',false,false,0);
insert into public.cs_journeys(id,title,description,units,flexible,position) values('university','Moving to university','Make your funding last, understand housing costs and navigate money away from home.','["Before you move", "Your first term"]'::jsonb,false,1);
insert into public.cs_lessons(id,position,title,description,reading,journey_id,journey_position,reading_cards,checklist,sources,reviewed_at) values('uni-term',100,'Make your money last the term','Turn a lump sum into a weekly plan.','Sam has £3,000 available for a 12-week term. After reserving £1,800 for rent and £240 for known travel costs, £960 remains: £80 a week for everything else. These are practice figures, not a recommended student budget. A balance can look generous while already being committed. List payment dates and all living costs before deciding what is available for food, study materials and social spending. Keep a margin for costs you cannot predict. Check your actual funding schedule and eligibility with your student finance body. Rules and payment patterns differ across the UK and by circumstances; a termly payment is an example, not a universal rule.','university',1,'["Sam has £3,000 available for a 12-week term. After reserving £1,800 for rent and £240 for known travel costs, £960 remains: £80 a week for everything else. These are practice figures, not a recommended student budget.", "A balance can look generous while already being committed. List payment dates and all living costs before deciding what is available for food, study materials and social spending. Keep a margin for costs you cannot predict.", "Check your actual funding schedule and eligibility with your student finance body. Rules and payment patterns differ across the UK and by circumstances; a termly payment is an example, not a universal rule."]'::jsonb,'["Write down the date and amount of your next confirmed funding payment.", "Reserve money for rent and known costs before setting a weekly allowance.", "Check whether your plan covers holidays as well as term time."]'::jsonb,'[{"title": "MoneyHelper · University budgeting", "url": "https://www.moneyhelper.org.uk/en/family-and-care/student-and-graduate-money/budgeting-for-college-or-university"}, {"title": "MoneyHelper · Budget planner", "url": "https://www.moneyhelper.org.uk/en/everyday-money/budgeting/budget-planner"}]'::jsonb,'2026-11-07');
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values('uni-term-1','uni-term',1,'Sam has £3,000 for 12 weeks, with £1,800 rent and £240 travel reserved. What is left per week?','["£80", "£250", "£100"]'::jsonb,0,'£3,000 − £1,800 − £240 = £960; £960 ÷ 12 = £80. Other expenses must still fit within it.');
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values('uni-term-2','uni-term',2,'Your account shows £900, but £650 rent is due before your next payment. What is a useful starting point?','["Assume your next funding will arrive early", "Reserve £650 and plan the remaining £250 around other costs", "Treat the whole £900 as spending money"]'::jsonb,1,'Separate money already committed before deciding what you can spend.');
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values('uni-term-3','uni-term',3,'Your friend receives funding three times a year. What should you use for your own plan?','["Their dates, because all UK funding is identical", "The balance you hope to have", "Your own award notice and payment dates"]'::jsonb,2,'Use confirmed details from your own funding provider, not another student’s schedule.');
insert into public.cs_lessons(id,position,title,description,reading,journey_id,journey_position,reading_cards,checklist,sources,reviewed_at) values('uni-home',101,'Look beyond the rent','Compare the total cost before committing.','A room advertised at £125 a week is not automatically cheaper than one at £145. Compare the number of weeks you must pay for, included bills, travel costs and money required before you move in. For example, £125 for 51 weeks costs £6,375 in rent. £145 for 40 weeks costs £5,800. Check whether you also need somewhere to live outside the shorter contract. Before signing or sending money, understand the agreement, deposit, guarantor requirements and who is responsible for payments. Housing rules vary by UK nation and type of accommodation. Ask the university housing team to explain unclear terms.','university',2,'["A room advertised at £125 a week is not automatically cheaper than one at £145. Compare the number of weeks you must pay for, included bills, travel costs and money required before you move in.", "For example, £125 for 51 weeks costs £6,375 in rent. £145 for 40 weeks costs £5,800. Check whether you also need somewhere to live outside the shorter contract.", "Before signing or sending money, understand the agreement, deposit, guarantor requirements and who is responsible for payments. Housing rules vary by UK nation and type of accommodation. Ask the university housing team to explain unclear terms."]'::jsonb,'["Compare rent over the full contract, not just one week.", "List bills, upfront payments and travel separately.", "Ask the university housing team to review terms you do not understand."]'::jsonb,'[{"title": "MoneyHelper · University budgeting", "url": "https://www.moneyhelper.org.uk/en/family-and-care/student-and-graduate-money/budgeting-for-college-or-university"}]'::jsonb,'2026-11-07');
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values('uni-home-1','uni-home',1,'Room A is £125 for 51 weeks; room B is £145 for 40 weeks. Ignoring other costs, which rent total is lower?','["They cost the same", "Room B: £5,800", "Room A: £6,375"]'::jsonb,1,'Multiply the weekly price by the full contract length. A lower weekly price can mean a higher total.');
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values('uni-home-2','uni-home',2,'A listing says “bills included”. What is worth checking before signing?','["Only the colour of the room", "Nothing: every possible bill must be covered", "Which bills, any usage caps and the full contract"]'::jsonb,2,'Clarify exactly what is included; do not assume a short advert contains all the terms.');
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values('uni-home-3','uni-home',3,'You do not understand a guarantor clause. What is the next step?','["Ask for an explanation before agreeing", "Sign now and read it later", "Ask a friend to sign without explaining it"]'::jsonb,0,'A guarantor may take on financial responsibilities. Get the clause explained before anyone agrees.');
insert into public.cs_lessons(id,position,title,description,reading,journey_id,journey_position,reading_cards,checklist,sources,reviewed_at) values('uni-shared',102,'Share a home, not confusion','Make a workable plan for household bills.','Four housemates estimate a shared bill at £120 a month and agree an equal split: £30 each. Decide who holds the account, when contributions arrive and how everyone can see the bill. A private agreement about splitting costs does not replace the supplier or tenancy contract. Check who is legally responsible and plan what happens if someone leaves or cannot pay. In Great Britain, households made up entirely of qualifying full-time students generally do not pay Council Tax; check the council’s evidence and application process. Mixed households need a separate check. Northern Ireland uses domestic rates instead, so do not assume the same exemption applies.','university',3,'["Four housemates estimate a shared bill at £120 a month and agree an equal split: £30 each. Decide who holds the account, when contributions arrive and how everyone can see the bill.", "A private agreement about splitting costs does not replace the supplier or tenancy contract. Check who is legally responsible and plan what happens if someone leaves or cannot pay.", "In Great Britain, households made up entirely of qualifying full-time students generally do not pay Council Tax; check the council’s evidence and application process. Mixed households need a separate check. Northern Ireland uses domestic rates instead, so do not assume the same exemption applies."]'::jsonb,'["Agree contributions and payment dates with housemates.", "Keep shared bills and payment records accessible to everyone involved.", "Check Council Tax or domestic rates with the relevant authority for your home."]'::jsonb,'[{"title": "MoneyHelper · Regular payments", "url": "https://www.moneyhelper.org.uk/en/everyday-money/banking/direct-debits-and-standing-orders"}, {"title": "GOV.UK · Full-time students and Council Tax", "url": "https://www.gov.uk/council-tax/discounts-for-full-time-students"}]'::jsonb,'2026-11-07');
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values('uni-shared-1','uni-shared',1,'A £120 monthly bill is shared equally between four people. What is each share?','["£40", "£25", "£30"]'::jsonb,2,'£120 divided by four is £30. Actual contributions depend on the agreement and bill.');
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values('uni-shared-2','uni-shared',2,'One housemate agrees to collect everyone’s share. What still needs checking?','["Who is responsible under the supplier’s contract", "Whether the private split cancels the contract", "Whether nobody has to keep records"]'::jsonb,0,'An informal split does not automatically change liability to the supplier.');
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values('uni-shared-3','uni-shared',3,'A student moves to Northern Ireland. Should they assume the Great Britain Council Tax exemption applies?','["Yes: showing a student card always cancels every bill", "No: check domestic rates rules for that property", "Yes: all UK property taxes have identical student rules"]'::jsonb,1,'Northern Ireland uses rates. Check the local rules rather than importing Council Tax assumptions.');
insert into public.cs_lessons(id,position,title,description,reading,journey_id,journey_position,reading_cards,checklist,sources,reviewed_at) values('uni-backup',103,'When the plan does not stretch','Spot borrowing risks and ask for support early.','An overdraft is borrowing, even if an arranged student overdraft currently charges no interest. Check the limit, conditions and what changes when student status ends; it is not extra income. If funding is delayed or essential costs do not fit, contact your university money or welfare team about available support. Help and eligibility vary. Avoid covering a continuing shortfall with repeated borrowing without advice. Treat an unexpected funding message asking for a password or urgent payment with caution. Open your provider’s official site independently or contact them using a known number, rather than following the message link.','university',4,'["An overdraft is borrowing, even if an arranged student overdraft currently charges no interest. Check the limit, conditions and what changes when student status ends; it is not extra income.", "If funding is delayed or essential costs do not fit, contact your university money or welfare team about available support. Help and eligibility vary. Avoid covering a continuing shortfall with repeated borrowing without advice.", "Treat an unexpected funding message asking for a password or urgent payment with caution. Open your provider’s official site independently or contact them using a known number, rather than following the message link."]'::jsonb,'["Find your university’s money advice or student support contact.", "Read the terms of any overdraft you already use.", "Check funding messages through a trusted channel."]'::jsonb,'[{"title": "MoneyHelper · University budgeting", "url": "https://www.moneyhelper.org.uk/en/family-and-care/student-and-graduate-money/budgeting-for-college-or-university"}, {"title": "MoneyHelper · Free debt advice", "url": "https://www.moneyhelper.org.uk/en/money-troubles/dealing-with-debt/debt-advice-locator"}]'::jsonb,'2026-11-07');
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values('uni-backup-1','uni-backup',1,'Your account includes a £500 arranged overdraft. How should you think about it?','["Borrowing that needs repaying under its terms", "An extra grant", "Money that never needs repaying while you study"]'::jsonb,0,'An overdraft remains debt, including during an interest-free period.');
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values('uni-backup-2','uni-backup',2,'Your funding is late and rent is due. Which is a useful early step?','["Take several loans before checking other options", "Contact student support and the accommodation provider", "Ignore all messages until funding arrives"]'::jsonb,1,'Explain the timing problem and ask what support or arrangements may be available.');
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values('uni-backup-3','uni-backup',3,'A text says your funding will be cancelled unless you enter your password through its link. What should you do?','["Enter your password quickly", "Forward the password to the sender instead", "Check through the provider’s official site independently"]'::jsonb,2,'Use a trusted route to verify the claim. Urgency is not proof that a message is genuine.');
insert into public.cs_journeys(id,title,description,units,flexible,position) values('independent','Managing money for the first time','Understand what comes in, what goes out and how to take the next step.','["Find your starting point", "Build a routine"]'::jsonb,true,2);
insert into public.cs_lessons(id,position,title,description,reading,journey_id,journey_position,reading_cards,checklist,sources,reviewed_at) values('own-map',110,'Make a simple money map','Start with information, not a perfect budget.','You do not need to understand everything today. Start with income, accounts you can access, regular bills and the next due dates. Use statements or official account information rather than guessing. If someone else used to handle money, list what is unknown as well as what you know. An unfamiliar payment is something to investigate, not automatically something to cancel. If this follows a death or another major change, ask the relevant bank or provider what access and documents are needed. This lesson is about your own day-to-day money; it does not establish authority to use someone else’s account.','independent',1,'["You do not need to understand everything today. Start with income, accounts you can access, regular bills and the next due dates. Use statements or official account information rather than guessing.", "If someone else used to handle money, list what is unknown as well as what you know. An unfamiliar payment is something to investigate, not automatically something to cancel.", "If this follows a death or another major change, ask the relevant bank or provider what access and documents are needed. This lesson is about your own day-to-day money; it does not establish authority to use someone else’s account."]'::jsonb,'["List your income sources and next expected dates.", "Find a recent statement for accounts you are authorised to access.", "Write down three unknowns to ask a bank or provider about."]'::jsonb,'[{"title": "MoneyHelper · Budget planner", "url": "https://www.moneyhelper.org.uk/en/everyday-money/budgeting/budget-planner"}]'::jsonb,'2026-11-07');
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values('own-map-1','own-map',1,'You have a statement but do not recognise a £42 payment. What is a useful first action?','["Check its reference and ask the bank or provider what it is", "Cancel every regular payment", "Assume it must be fraud without checking"]'::jsonb,0,'Identify the payment and any contractual obligation before deciding what to change.');
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values('own-map-2','own-map',2,'Which information helps build an initial money map?','["A friend’s monthly spending", "Income dates, bill dates and amounts", "Only the account balance today"]'::jsonb,1,'Timing and commitments matter as well as the current balance.');
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values('own-map-3','own-map',3,'You know the login for an account in someone else’s name. Does that establish authority to use it?','["Yes: knowing the password is enough", "Yes: if you only make small payments", "No: ask the bank about the appropriate process"]'::jsonb,2,'Knowing login details is not the same as being authorised to manage an account.');
insert into public.cs_lessons(id,position,title,description,reading,journey_id,journey_position,reading_cards,checklist,sources,reviewed_at) values('own-payments',111,'Read the payments on your statement','Understand Direct Debits and standing orders.','A Direct Debit lets a company collect an agreed payment from your bank account. A standing order is an instruction you set up to send a fixed amount regularly. A recurring card payment uses your card details. If a Direct Debit has been collected in error, ask your bank about the Direct Debit Guarantee. A refund for a payment error does not erase a legitimate underlying debt. Cancelling a payment instruction does not necessarily cancel the contract or what you owe. Check the agreement and contact the provider about ending or changing a service.','independent',2,'["A Direct Debit lets a company collect an agreed payment from your bank account. A standing order is an instruction you set up to send a fixed amount regularly. A recurring card payment uses your card details.", "If a Direct Debit has been collected in error, ask your bank about the Direct Debit Guarantee. A refund for a payment error does not erase a legitimate underlying debt.", "Cancelling a payment instruction does not necessarily cancel the contract or what you owe. Check the agreement and contact the provider about ending or changing a service."]'::jsonb,'["Identify one Direct Debit, standing order or card subscription on your statement.", "Check the next amount and date with the provider if unclear.", "Before cancelling, check the agreement and any remaining amount owed."]'::jsonb,'[{"title": "MoneyHelper · Regular payments", "url": "https://www.moneyhelper.org.uk/en/everyday-money/banking/direct-debits-and-standing-orders"}]'::jsonb,'2026-11-07');
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values('own-payments-1','own-payments',1,'You tell your bank to send £50 to your savings account every month. What is that?','["A payslip deduction", "A standing order", "A Direct Debit collected by a company"]'::jsonb,1,'A standing order is a regular fixed payment you instruct your bank to send.');
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values('own-payments-2','own-payments',2,'You cancel the Direct Debit for a contract that still has six months left. What follows?','["The contract automatically disappears", "The provider must refund all past payments", "You may still owe payments under the contract"]'::jsonb,2,'Stopping the bank instruction is different from ending the agreement.');
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values('own-payments-3','own-payments',3,'A company takes a Direct Debit twice by mistake. Who can you ask about the Guarantee?','["Your bank", "Only your employer", "An unrelated social-media account"]'::jsonb,0,'Your bank can help with a Direct Debit error. Any valid underlying bill still needs resolving.');
insert into public.cs_lessons(id,position,title,description,reading,journey_id,journey_position,reading_cards,checklist,sources,reviewed_at) values('own-month',112,'Plan what you can actually spend','Use a realistic monthly picture.','Alex receives £1,600 a month. Regular commitments are £1,050 and estimated food and travel are £350. That leaves £200 before any other costs, savings or debt payments. Include costs that do not arrive every month. An expected £180 annual expense would need £15 a month set aside over a full year if starting from zero. A budget is a working plan. Review real spending, update estimates and look for support if essentials exceed income. A shortfall is information, not a personal failure.','independent',3,'["Alex receives £1,600 a month. Regular commitments are £1,050 and estimated food and travel are £350. That leaves £200 before any other costs, savings or debt payments.", "Include costs that do not arrive every month. An expected £180 annual expense would need £15 a month set aside over a full year if starting from zero.", "A budget is a working plan. Review real spending, update estimates and look for support if essentials exceed income. A shortfall is information, not a personal failure."]'::jsonb,'["Use recent statements to estimate regular and variable costs.", "Add a monthly allowance for known annual costs.", "Set a short weekly check-in to compare your plan with reality."]'::jsonb,'[{"title": "MoneyHelper · Budget planner", "url": "https://www.moneyhelper.org.uk/en/everyday-money/budgeting/budget-planner"}]'::jsonb,'2026-11-07');
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values('own-month-1','own-month',1,'Alex has £1,600 income, £1,050 commitments and £350 food and travel. What remains?','["£550", "£300", "£200"]'::jsonb,2,'£1,600 − £1,050 − £350 = £200. Other costs may still need covering.');
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values('own-month-2','own-month',2,'You need £180 for an annual expense in 12 months, starting from zero. What is the monthly amount?','["£15", "£18", "£30"]'::jsonb,0,'£180 ÷ 12 = £15. A shorter timeframe would require a different amount.');
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values('own-month-3','own-month',3,'Your essential spending is higher than your income. What does the plan tell you?','["The gap will disappear if you stop tracking it", "There is a gap to address with support or changes", "You have failed the task"]'::jsonb,1,'The plan makes a problem visible so you can consider realistic options and support.');
insert into public.cs_lessons(id,position,title,description,reading,journey_id,journey_position,reading_cards,checklist,sources,reviewed_at) values('own-support',113,'Make the next call easier','Get help without giving away control.','Prepare a short list before contacting a bank or provider: what you want to understand, the account reference and the relevant dates. Keep a note of agreed next steps. Use contact details from a trusted statement, card or official website. Never share a PIN or a one-time security code with someone who has unexpectedly contacted you. You can ask a provider about accessible communication, extra time or support from a trusted person. Ask about their formal arrangements instead of sharing account passwords.','independent',4,'["Prepare a short list before contacting a bank or provider: what you want to understand, the account reference and the relevant dates. Keep a note of agreed next steps.", "Use contact details from a trusted statement, card or official website. Never share a PIN or a one-time security code with someone who has unexpectedly contacted you.", "You can ask a provider about accessible communication, extra time or support from a trusted person. Ask about their formal arrangements instead of sharing account passwords."]'::jsonb,'["Choose one unanswered question and write it down.", "Find the provider’s contact details independently.", "Record the date, next step and any reference after the conversation."]'::jsonb,'[{"title": "MoneyHelper · Budget planner", "url": "https://www.moneyhelper.org.uk/en/everyday-money/budgeting/budget-planner"}, {"title": "MoneyHelper · Free debt advice", "url": "https://www.moneyhelper.org.uk/en/money-troubles/dealing-with-debt/debt-advice-locator"}]'::jsonb,'2026-11-07');
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values('own-support-1','own-support',1,'Someone calls claiming to be your bank and asks for a one-time code. What is safer?','["End the call and contact the bank through a trusted route", "Read out the code to prove who you are", "Send the code by text instead"]'::jsonb,0,'Do not give an unexpected caller a security code. Verify independently.');
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values('own-support-2','own-support',2,'You want a trusted relative to help with calls. What should you ask the provider?','["Whether they can remove all account security", "What authorised support arrangements they offer", "How to share your password with everyone"]'::jsonb,1,'Formal support can help you get assistance while keeping access appropriate.');
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values('own-support-3','own-support',3,'After agreeing a payment change, what is useful to keep?','["Only the person’s first name", "No record because it was discussed verbally", "The date, agreed terms and reference"]'::jsonb,2,'A clear record helps you follow up and check whether the agreed change happened.');
insert into public.cs_journeys(id,title,description,units,flexible,position) values('bills','Struggling to keep up with bills','Find a manageable next step. No streaks, deadlines or pressure to finish.','["Understand what needs attention", "Find support that fits"]'::jsonb,true,3);
insert into public.cs_lessons(id,position,title,description,reading,journey_id,journey_position,reading_cards,checklist,sources,reviewed_at) values('bills-first',120,'Work out what needs attention first','Start with consequences, not the loudest reminder.','If there is not enough money for everything, begin with essential living costs and bills whose non-payment could have serious consequences. Rent arrears, for example, can threaten your home; a louder credit-card reminder does not automatically make that bill more urgent. Priority debt categories and available procedures differ across England, Wales, Scotland and Northern Ireland. Use guidance for your nation and speak with a free debt adviser about your circumstances. A court deadline, eviction notice or risk of losing an essential service needs prompt help. You do not need to finish this course first: the support link is always available.','bills',1,'["If there is not enough money for everything, begin with essential living costs and bills whose non-payment could have serious consequences. Rent arrears, for example, can threaten your home; a louder credit-card reminder does not automatically make that bill more urgent.", "Priority debt categories and available procedures differ across England, Wales, Scotland and Northern Ireland. Use guidance for your nation and speak with a free debt adviser about your circumstances.", "A court deadline, eviction notice or risk of losing an essential service needs prompt help. You do not need to finish this course first: the support link is always available."]'::jsonb,'["List overdue bills and any notices or deadlines.", "Flag anything affecting your home, essential services or court action.", "Use the free advice link if you are unsure what needs attention first."]'::jsonb,'[{"title": "StepChange · Priority bills by UK nation", "url": "https://www.stepchange.org/debt-info/dealing-with-debt-problems/what-debts-to-pay-first.aspx"}, {"title": "MoneyHelper · Free debt advice", "url": "https://www.moneyhelper.org.uk/en/money-troubles/dealing-with-debt/debt-advice-locator"}]'::jsonb,'2026-11-07');
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values('bills-first-1','bills-first',1,'You have rent arrears and a strongly worded credit-card reminder. What should guide priorities?','["The consequences of missing each payment and your circumstances", "Which company sends the most messages", "Which envelope looks most official"]'::jsonb,0,'Priority is about consequences, including risks to your home, not pressure from the loudest creditor.');
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values('bills-first-2','bills-first',2,'A court notice gives a deadline next week. What is a sensible next step?','["Throw it away because it is stressful", "Seek appropriate advice promptly and keep the notice", "Wait until every lesson is finished"]'::jsonb,1,'A learning app should not delay help with an urgent deadline.');
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values('bills-first-3','bills-first',3,'You find an England-specific debt procedure but live in Scotland. What should you do?','["Assume all UK debt procedures are identical", "Apply without checking where it operates", "Check Scottish guidance or ask an adviser"]'::jsonb,2,'Processes and options vary across UK nations; use guidance that fits your location.');
insert into public.cs_lessons(id,position,title,description,reading,journey_id,journey_position,reading_cards,checklist,sources,reviewed_at) values('bills-contact',121,'Prepare a conversation with a provider','Explain the problem and ask about realistic options.','Before calling, note your income, essential costs and what is overdue. You can say: “I am struggling with this bill. Can we discuss support and an arrangement based on what I can afford?” If you have £1,300 income and £1,280 essential costs in a practice budget, the remaining £20 must be considered alongside all other commitments. It is not automatically an offer you should make to one creditor. Ask what options are available, how they affect your account and whether interest or charges can be considered. Do not promise an amount you cannot maintain; an adviser can help assess affordability.','bills',2,'["Before calling, note your income, essential costs and what is overdue. You can say: “I am struggling with this bill. Can we discuss support and an arrangement based on what I can afford?”", "If you have £1,300 income and £1,280 essential costs in a practice budget, the remaining £20 must be considered alongside all other commitments. It is not automatically an offer you should make to one creditor.", "Ask what options are available, how they affect your account and whether interest or charges can be considered. Do not promise an amount you cannot maintain; an adviser can help assess affordability."]'::jsonb,'["Write a brief explanation of what has changed.", "Have your income, essential spending and other debts available.", "Ask for any agreed arrangement in writing and check the next review date."]'::jsonb,'[{"title": "MoneyHelper · Free debt advice", "url": "https://www.moneyhelper.org.uk/en/money-troubles/dealing-with-debt/debt-advice-locator"}, {"title": "MoneyHelper · Budget planner", "url": "https://www.moneyhelper.org.uk/en/everyday-money/budgeting/budget-planner"}]'::jsonb,'2026-11-07');
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values('bills-contact-1','bills-contact',1,'Your budget leaves £20 before other debts. A provider requests £80 a month. What is appropriate?','["Assume £20 must all go to this provider", "Explain the affordability gap and seek help with a realistic arrangement", "Promise £80 even though you cannot maintain it"]'::jsonb,1,'An arrangement should reflect the full budget, including other obligations.');
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values('bills-contact-2','bills-contact',2,'Which opening explains the situation usefully?','["I will pay any amount you suggest", "I cannot call until I have solved everything", "I am struggling to pay; can we discuss support and what is affordable?"]'::jsonb,2,'You can ask for help before you have a complete solution.');
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values('bills-contact-3','bills-contact',3,'A new payment plan is proposed. What should you clarify?','["Amounts, dates, charges and how the account will be treated", "Only whether the call was short", "Nothing once the provider says yes"]'::jsonb,0,'Understand the terms and consequences before relying on an arrangement.');
insert into public.cs_lessons(id,position,title,description,reading,journey_id,journey_position,reading_cards,checklist,sources,reviewed_at) values('bills-borrow',122,'Pause before borrowing to cover a gap','Compare the full commitment, not just today’s payment.','Borrowing can move a bill into the future without fixing a regular shortfall. Before taking new credit to cover existing debts, consider free debt advice and the full repayment commitment. In a simplified comparison, option A requires £25 for six months: £150 total. Option B requires £18 for ten months: £180 total. A smaller monthly payment can still cost more overall. Buy now, pay later is still a payment commitment. Check due dates, late-payment consequences and how it fits alongside rent, food and existing bills. Avoid pressure to decide immediately.','bills',3,'["Borrowing can move a bill into the future without fixing a regular shortfall. Before taking new credit to cover existing debts, consider free debt advice and the full repayment commitment.", "In a simplified comparison, option A requires £25 for six months: £150 total. Option B requires £18 for ten months: £180 total. A smaller monthly payment can still cost more overall.", "Buy now, pay later is still a payment commitment. Check due dates, late-payment consequences and how it fits alongside rent, food and existing bills. Avoid pressure to decide immediately."]'::jsonb,'["Write down the total repayment, dates and charges for any offer.", "Check whether the gap is one-off or repeats every month.", "Get free advice before taking new borrowing to repay existing debts."]'::jsonb,'[{"title": "MoneyHelper · Free debt advice", "url": "https://www.moneyhelper.org.uk/en/money-troubles/dealing-with-debt/debt-advice-locator"}, {"title": "MoneyHelper · Budget planner", "url": "https://www.moneyhelper.org.uk/en/everyday-money/budgeting/budget-planner"}]'::jsonb,'2026-11-07');
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values('bills-borrow-1','bills-borrow',1,'Which simplified option costs less overall: £25 for six months or £18 for ten?','["£18 for ten months: £180", "Both cost the same", "£25 for six months: £150"]'::jsonb,2,'Multiply every instalment by the number of payments. Include fees when comparing real offers.');
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values('bills-borrow-2','bills-borrow',2,'Your income falls short of essentials every month. What does a new loan change?','["It adds a repayment; it does not by itself solve the ongoing gap", "It creates permanent extra income", "It removes all future bills"]'::jsonb,0,'Repeated shortfalls need a wider plan and support, not just moving costs forward.');
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values('bills-borrow-3','bills-borrow',3,'A checkout offers four later payments. What should you treat them as?','["Payments you can ignore after receiving the item", "Future commitments in your budget", "A discount that removes the cost"]'::jsonb,1,'Later payments still need funding and can have consequences if missed.');
insert into public.cs_lessons(id,position,title,description,reading,journey_id,journey_position,reading_cards,checklist,sources,reviewed_at) values('bills-help',123,'Find support without having everything ready','Take one manageable next step.','Free, confidential debt advice is available. MoneyHelper’s locator lets you find online, telephone or face-to-face support. An adviser can help you understand options and possible entitlements. Bring what you have: recent bills, income information and letters are useful, but do not let an incomplete folder stop you seeking help. Explain any urgent deadlines first. Support schemes and debt options depend on circumstances and where you live. Do not assume a solution mentioned online is available or suitable for everyone; ask an adviser to explain the consequences.','bills',4,'["Free, confidential debt advice is available. MoneyHelper’s locator lets you find online, telephone or face-to-face support. An adviser can help you understand options and possible entitlements.", "Bring what you have: recent bills, income information and letters are useful, but do not let an incomplete folder stop you seeking help. Explain any urgent deadlines first.", "Support schemes and debt options depend on circumstances and where you live. Do not assume a solution mentioned online is available or suitable for everyone; ask an adviser to explain the consequences."]'::jsonb,'["Open the advice locator and choose a contact method that suits you.", "Gather the bills and income details you already have.", "Write any urgent deadline at the top of your notes."]'::jsonb,'[{"title": "MoneyHelper · Free debt advice", "url": "https://www.moneyhelper.org.uk/en/money-troubles/dealing-with-debt/debt-advice-locator"}, {"title": "StepChange · Priority bills by UK nation", "url": "https://www.stepchange.org/debt-info/dealing-with-debt-problems/what-debts-to-pay-first.aspx"}]'::jsonb,'2026-11-07');
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values('bills-help-1','bills-help',1,'You are missing some statements but have an urgent bill problem. Should you wait?','["No: seek help and explain which information is missing", "Yes: advisers only help with perfect records", "Yes: wait until all deadlines have passed"]'::jsonb,0,'Start with the information you have, especially when there is an urgent issue.');
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values('bills-help-2','bills-help',2,'What can a free debt adviser help you explore?','["A requirement to take a new loan", "Options and possible support suited to your circumstances", "A guaranteed outcome for every person"]'::jsonb,1,'Advice helps assess your situation; it does not mean one solution fits everyone.');
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values('bills-help-3','bills-help',3,'A friend says one debt solution will solve everyone’s problems. What should you do?','["Choose it because it helped your friend", "Assume it works identically across the UK", "Ask an adviser about eligibility, alternatives and consequences"]'::jsonb,2,'A suitable option depends on your circumstances and the relevant UK nation.');
insert into public.cs_journeys(id,title,description,units,flexible,position) values('first-job','Starting your first job','Understand your payslip, bridge your first payday and build a useful routine.','["Your first payday", "Your next few months"]'::jsonb,false,4);
insert into public.cs_lessons(id,position,title,description,reading,journey_id,journey_position,reading_cards,checklist,sources,reviewed_at) values('job-payslip',130,'Read your first payslip','Know the difference between gross and take-home pay.','Gross pay is earnings before deductions; net pay is what remains after them. In a fictional payslip, £2,000 gross minus £300 total deductions gives £1,700 net. These figures illustrate subtraction, not UK tax rates. A payslip shows earnings and relevant deductions, such as Income Tax and National Insurance. Check the pay period, hours where relevant and the amount that reaches your bank. If something does not match your agreed pay or hours, ask payroll to explain it. Keep payslips so you can check changes and provide evidence of earnings when needed.','first-job',1,'["Gross pay is earnings before deductions; net pay is what remains after them. In a fictional payslip, £2,000 gross minus £300 total deductions gives £1,700 net. These figures illustrate subtraction, not UK tax rates.", "A payslip shows earnings and relevant deductions, such as Income Tax and National Insurance. Check the pay period, hours where relevant and the amount that reaches your bank.", "If something does not match your agreed pay or hours, ask payroll to explain it. Keep payslips so you can check changes and provide evidence of earnings when needed."]'::jsonb,'["Find gross pay, deductions and net pay on your own payslip.", "Compare the period and hours with your records.", "Ask payroll about any unexplained difference."]'::jsonb,'[{"title": "GOV.UK · Payslips", "url": "https://www.gov.uk/payslips"}]'::jsonb,'2026-11-07');
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values('job-payslip-1','job-payslip',1,'A fictional payslip shows £2,000 gross and £300 total deductions. What is net pay?','["£1,700", "£2,300", "£2,000"]'::jsonb,0,'Net pay is gross pay minus deductions: £2,000 − £300 = £1,700.');
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values('job-payslip-2','job-payslip',2,'Which amount normally forms the starting point for your spending plan?','["The employer’s total staffing cost", "Take-home pay after deductions", "Gross pay before deductions"]'::jsonb,1,'Use money actually available to you, then account for any other income or commitments.');
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values('job-payslip-3','job-payslip',3,'Your paid hours do not match your records. What helps resolve it?','["Assume the bank can change your payslip", "Ignore every future payslip", "Compare the pay period and raise the difference with payroll"]'::jsonb,2,'Check the period first, then ask payroll to investigate with your records.');
insert into public.cs_lessons(id,position,title,description,reading,journey_id,journey_position,reading_cards,checklist,sources,reviewed_at) values('job-payday',131,'Bridge the gap to payday','Plan dates as well as amounts.','Starting work does not always mean being paid immediately. Ask about the payroll cut-off, first payment date and whether the first pay covers a full or partial period. Riley has £240 before payday. Known travel is £60, food is £80 and a phone bill is £20, leaving £80 for other needs. These are practice figures; include your own essentials before making plans. Once pay becomes regular, map bills against pay dates. If the timing does not fit, ask providers whether a due-date change is possible; confirm it before relying on it.','first-job',2,'["Starting work does not always mean being paid immediately. Ask about the payroll cut-off, first payment date and whether the first pay covers a full or partial period.", "Riley has £240 before payday. Known travel is £60, food is £80 and a phone bill is £20, leaving £80 for other needs. These are practice figures; include your own essentials before making plans.", "Once pay becomes regular, map bills against pay dates. If the timing does not fit, ask providers whether a due-date change is possible; confirm it before relying on it."]'::jsonb,'["Confirm your first payday and the period it covers.", "List essential costs between now and that date.", "Check bill dates and ask about changes if the timing is difficult."]'::jsonb,'[{"title": "MoneyHelper · Budget planner", "url": "https://www.moneyhelper.org.uk/en/everyday-money/budgeting/budget-planner"}, {"title": "MoneyHelper · Regular payments", "url": "https://www.moneyhelper.org.uk/en/everyday-money/banking/direct-debits-and-standing-orders"}]'::jsonb,'2026-11-07');
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values('job-payday-1','job-payday',1,'Riley has £240, with £60 travel, £80 food and £20 phone due. What remains?','["£160", "£80", "£100"]'::jsonb,1,'£240 − £60 − £80 − £20 = £80, before any unlisted costs.');
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values('job-payday-2','job-payday',2,'You start halfway through a payroll period. What should you check?','["Only the annual salary", "Whether every employer pays on the same day", "The first pay date, cut-off and period covered"]'::jsonb,2,'The first payment may cover a partial period or arrive later than expected.');
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values('job-payday-3','job-payday',3,'A bill is due before payday. What is a useful step?','["Ask the provider about timing options and confirm any change", "Move the date in your own calendar and assume it is agreed", "Ignore the bill because you now have a job"]'::jsonb,0,'A reminder change does not change a contractual due date; speak with the provider.');
insert into public.cs_lessons(id,position,title,description,reading,journey_id,journey_position,reading_cards,checklist,sources,reviewed_at) values('job-tax',132,'Make sense of deductions','Know what to check and where to ask.','PAYE is the system employers use to collect Income Tax from pay. National Insurance is a separate deduction. Your tax code helps your employer work out tax; it is not itself a percentage rate. If tax looks unexpected, check the employment details and tax code through HMRC’s official service and ask payroll about the calculation. A first payslip alone does not prove there is an error. Student loan deductions depend on your loan plan and earnings rules. Thresholds and tax treatment can change, and Income Tax differs in Scotland. Use current official guidance rather than treating these fictional examples as a personal calculation.','first-job',3,'["PAYE is the system employers use to collect Income Tax from pay. National Insurance is a separate deduction. Your tax code helps your employer work out tax; it is not itself a percentage rate.", "If tax looks unexpected, check the employment details and tax code through HMRC’s official service and ask payroll about the calculation. A first payslip alone does not prove there is an error.", "Student loan deductions depend on your loan plan and earnings rules. Thresholds and tax treatment can change, and Income Tax differs in Scotland. Use current official guidance rather than treating these fictional examples as a personal calculation."]'::jsonb,'["Locate your tax code and deduction labels.", "Check your employment information through HMRC if something looks wrong.", "Ask payroll what each unfamiliar deduction relates to."]'::jsonb,'[{"title": "GOV.UK · Check the tax on your payslip", "url": "https://www.gov.uk/guidance/check-if-the-tax-on-your-payslip-is-correct"}, {"title": "GOV.UK · Payslips", "url": "https://www.gov.uk/payslips"}]'::jsonb,'2026-11-07');
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values('job-tax-1','job-tax',1,'Your payslip has both Income Tax and National Insurance. Are they the same deduction?','["Yes: one must always be a duplicate", "Yes: the labels are interchangeable", "No: they are separate"]'::jsonb,2,'They are distinct deductions. Seeing both does not itself mean tax was taken twice.');
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values('job-tax-2','job-tax',2,'Your tax code looks unfamiliar. What should you do?','["Check HMRC’s official service and ask payroll if needed", "Use a random online code for everyone", "Assume the code is your tax percentage"]'::jsonb,0,'A tax code helps determine how pay is taxed; check the details rather than guessing.');
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values('job-tax-3','job-tax',3,'A colleague has a different student loan deduction. What matters?','["Your deduction must be wrong", "Their plan and earnings rules may differ from yours", "Everyone must pay the identical amount"]'::jsonb,1,'Different plans and pay levels can produce different deductions. Check your own details.');
insert into public.cs_lessons(id,position,title,description,reading,journey_id,journey_position,reading_cards,checklist,sources,reviewed_at) values('job-future',133,'Understand your pension and build a buffer','Balance future saving with money you can access.','A workplace pension is for retirement; it is different from an accessible emergency fund. Eligible workers are automatically enrolled and employers contribute under the applicable rules. Check the enrolment letter for your scheme. Your pension contribution may reduce take-home pay, while employer contributions add to the pension. If you are considering leaving, understand what contributions or benefits you would lose and ask for guidance first. For short-term surprises, choose an affordable amount for accessible savings only after considering essentials and your circumstances. A manageable plan can change over time; there is no single amount everyone must save.','first-job',4,'["A workplace pension is for retirement; it is different from an accessible emergency fund. Eligible workers are automatically enrolled and employers contribute under the applicable rules. Check the enrolment letter for your scheme.", "Your pension contribution may reduce take-home pay, while employer contributions add to the pension. If you are considering leaving, understand what contributions or benefits you would lose and ask for guidance first.", "For short-term surprises, choose an affordable amount for accessible savings only after considering essentials and your circumstances. A manageable plan can change over time; there is no single amount everyone must save."]'::jsonb,'["Read your pension enrolment letter and contribution details.", "Check how the contribution appears on your payslip.", "Consider an affordable accessible buffer for short-term costs."]'::jsonb,'[{"title": "GOV.UK · Joining a workplace pension", "url": "https://www.gov.uk/workplace-pensions/joining-a-workplace-pension"}, {"title": "MoneyHelper · Budget planner", "url": "https://www.moneyhelper.org.uk/en/everyday-money/budgeting/budget-planner"}]'::jsonb,'2026-11-07');
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values('job-future-1','job-future',1,'You may need money for an unexpected expense next month. Which distinction matters?','["A pension is retirement saving, not an everyday emergency pot", "A pension is identical to a current account", "All savings can always be withdrawn immediately"]'::jsonb,0,'Access rules differ. Retirement savings should not be treated as readily available spending money.');
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values('job-future-2','job-future',2,'You are thinking about leaving your workplace pension. What should you understand first?','["Nothing: leaving never changes any benefits", "The effect on your contributions and employer contributions", "Only the colour of the scheme’s website"]'::jsonb,1,'Review the scheme and get guidance on consequences rather than deciding from one payslip line.');
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values('job-future-3','job-future',3,'You cannot afford a suggested savings target after essentials. What is reasonable?','["Borrow solely to hit the target", "Treat the suggested amount as compulsory", "Choose a manageable plan or seek support, then review it"]'::jsonb,2,'Saving should fit your circumstances; an arbitrary target should not replace essentials.');
 insert into cs_attempts values(p_attempt,p_learner,p_lesson,p_answers,score_count,total_count,passed_result,now());
  insert into cs_completions(learner_id,lesson_id,xp) values(p_learner,p_lesson,l.xp) on conflict do nothing;
